@prefix cdi: <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/codelist/qualityFlag> ;
            sh:resultMessage "A DDI-CDI CodeList should be defined by at least one cdi:isDefinedBy Concept (or id-reference)" ;
            sh:resultPath cdi:isDefinedBy ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A DDI-CDI CodeList should be defined by at least one cdi:isDefinedBy Concept (or id-reference)" ;
                    sh:minCount 1 ;
                    sh:path cdi:isDefinedBy ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/codelist/qualityFlag> ;
            sh:resultMessage "cdi:allowsDuplicates indicates whether duplicate members are permitted" ;
            sh:resultPath cdi:allowsDuplicates ;
            sh:resultSeverity sh:Info ;
            sh:sourceConstraintComponent sh:DatatypeConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:boolean ;
                    sh:message "cdi:allowsDuplicates indicates whether duplicate members are permitted" ;
                    sh:path cdi:allowsDuplicates ;
                    sh:severity sh:Info ] ;
            sh:value "not-a-boolean" ] .

